'use strict';
(() => {
const ids=['date','reference','recipient','subject','salutation','body','closing','name','title'];
const form=document.getElementById('letter-form'),preview=document.getElementById('letter-preview'),status=document.getElementById('letter-status');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const details=()=>Object.fromEntries(ids.map(id=>[id,document.getElementById('letter-'+id).value.trim()]));
const lines=s=>esc(s).replace(/\n/g,'<br>');
const dateLabel=s=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return '';const date=new Date(s+'T12:00:00');return Number.isNaN(date.getTime())?'':date.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});};
const logoUrl=new URL('assets/gems-logo.png',location.href).href;
const header=src=>`<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;border-bottom:3px solid #ed921f;font-family:Arial;"><tr><td valign="top" width="52%" style="vertical-align:top;padding-bottom:20px;"><img src="${src}" width="245" height="100" alt="GEMS Group — Green Economies Made Simple" style="display:block;width:245px;height:100px;"></td><td align="right" valign="top" style="vertical-align:top;padding-bottom:20px;font-size:11px;line-height:18px;color:#52635a;"><strong style="font-size:15px;color:#006632;">GEMS/WASTE Advisers</strong><br>PO Box 2504, Chigumula,<br>Blantyre, Malawi<br><span style="font-size:10px;">Reg: COYR-RE7175A CG158</span></td></tr></table>`;
const footer=()=>`<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;border-top:2px solid #006632;font-family:Arial;font-size:9px;line-height:16px;color:#52635a;"><tr><td style="padding-top:12px;"><strong style="color:#006632;">Green Economies Made Simple</strong><br><a href="https://www.greeneconomiesmadesimple.org/" style="color:#52635a;text-decoration:none;">greeneconomiesmadesimple.org</a></td><td align="right" style="padding-top:12px;"><a href="https://www.wasteadvisersmw.org/" style="color:#52635a;text-decoration:none;">wasteadvisersmw.org</a><br><a href="https://mustardlimited.com/" style="color:#52635a;text-decoration:none;">mustardlimited.com</a></td></tr></table>`;
function bodyHtml(d){return `<div style="font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#26392f;padding:28px 0 36px;">${d.date||d.reference?`<table width="100%" role="presentation" style="font-family:Arial;font-size:11px;color:#52635a;margin-bottom:26px;"><tr><td>${esc(dateLabel(d.date))}</td><td align="right">${d.reference?'Ref: '+esc(d.reference):''}</td></tr></table>`:''}${d.recipient?`<p style="margin:0 0 26px;">${lines(d.recipient)}</p>`:''}${d.subject?`<p style="font-weight:bold;color:#006632;font-size:14px;margin:0 0 22px;">${esc(d.subject)}</p>`:''}${d.salutation?`<p style="margin:0 0 18px;">${esc(d.salutation)}</p>`:''}${d.body.split(/\n\s*\n/).filter(Boolean).map(p=>`<p style="margin:0 0 16px;">${lines(p)}</p>`).join('')}${d.closing||d.name||d.title?`<div style="margin-top:30px;">${d.closing?`<p style="margin:0 0 36px;">${esc(d.closing)}</p>`:''}<p style="margin:0;"><strong>${esc(d.name)}</strong>${d.title?'<br>'+esc(d.title):''}</p></div>`:''}</div>`;}
function letterHtml(d,src=logoUrl){return `<div class="letter-sheet" style="font-family:Arial,Helvetica,sans-serif;background:#fff;color:#26392f;">${header(src)}<div class="letter-copy-space">${bodyHtml(d)}</div>${footer()}</div>`;}
function render(){preview.innerHTML=letterHtml(details());}
function message(text,error=false){status.textContent=text;status.classList.toggle('error',error);}
form.addEventListener('input',()=>{render();const button=document.getElementById('letter-copy');button.textContent='Copy letterhead';button.classList.remove('copied');message('Preview updated. Ready to copy or download.');});
form.addEventListener('submit',event=>event.preventDefault());
let logoPromise;
function logo(){if(!logoPromise)logoPromise=fetch(logoUrl).then(async response=>{if(!response.ok)throw Error('Logo unavailable');const bytes=new Uint8Array(await response.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return {data:'data:image/png;base64,'+btoa(binary),hex:Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('')};}).catch(error=>{logoPromise=null;throw error;});return logoPromise;}
const rtf=s=>String(s).split('').map(c=>c==='\\'?'\\\\':c==='{'?'\\{':c==='}'?'\\}':c==='\n'?'\\line ':c.charCodeAt(0)>127?'\\u'+(c.charCodeAt(0)>32767?c.charCodeAt(0)-65536:c.charCodeAt(0))+'?':c).join('');
function word(d,image){const p=(text,extra='')=>`\\pard\\sa200\\sl300\\slmult1\\f0\\fs22\\cf2 ${extra}${rtf(text)}\\par\n`;return `{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}{\\colortbl;\\red0\\green102\\blue50;\\red38\\green57\\blue47;\\red237\\green146\\blue31;\\red82\\green99\\blue90;}\\paperw11906\\paperh16838\\margl1134\\margr1134\\margt3000\\margb1400\\headery650\\footery650\\uc1\n{\\header\\trowd\\trgaph0\\cellx5000\\cellx9638\\pard\\intbl {\\pict\\pngblip\\picwgoal3675\\pichgoal1500 ${image.hex}}\\cell\\pard\\intbl\\qr\\f0\\fs20\\cf1\\b GEMS/WASTE Advisers\\b0\\cf4\\line PO Box 2504, Chigumula,\\line Blantyre, Malawi\\line\\fs17 Reg: COYR-RE7175A CG158\\cell\\row\\pard\\brdrb\\brdrs\\brdrw24\\brdrcf3\\sa200\\par}\n{\\footer\\pard\\brdrt\\brdrs\\brdrw18\\brdrcf1\\sb160\\f0\\fs17\\cf1\\b Green Economies Made Simple\\b0\\line\\cf4 greeneconomiesmadesimple.org | wasteadvisersmw.org | mustardlimited.com\\par}\n${d.date?p(dateLabel(d.date),'\\cf4 '):''}${d.reference?p('Ref: '+d.reference,'\\cf4 '):''}${d.recipient?p(d.recipient):''}${d.subject?p(d.subject,'\\b\\cf1 '):''}\\b0\n${d.salutation?p(d.salutation):''}${d.body.split(/\n\s*\n/).filter(Boolean).map(text=>p(text)).join('')}${d.closing?p(d.closing)+'\\pard\\sa520\\par ':''}${d.name?p(d.name,'\\b '):''}\\b0 ${d.title?p(d.title):''}}`;}
function download(content,type,extension){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download='GEMS-Letterhead.'+extension;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function action(id,fn){const button=document.getElementById(id);button.disabled=true;try{await fn();}catch{message('Unable to prepare your letterhead. Check your connection and try again.',true);}finally{button.disabled=false;}}
document.getElementById('letter-html').addEventListener('click',()=>action('letter-html',async()=>{const image=await logo();download(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GEMS Letterhead</title><style>body{margin:0;background:#edf2ee}.letter-sheet{box-sizing:border-box;width:210mm;min-height:297mm;margin:20px auto;padding:20mm;display:flex;flex-direction:column}.letter-copy-space{flex:1;min-height:185mm}p{orphans:3;widows:3}@page{size:A4;margin:0}@media print{body{background:#fff}.letter-sheet{margin:0;width:auto}}</style></head><body>${letterHtml(details(),image.data)}</body></html>`,'text/html;charset=utf-8','html');message('HTML downloaded with the logo embedded.');}));
document.getElementById('letter-word').addEventListener('click',()=>action('letter-word',async()=>{download(word(details(),await logo()),'application/rtf','rtf');message('Downloaded. Open the RTF file in Word, edit your letter, and save as a Word document.');}));
document.getElementById('letter-copy').addEventListener('click',()=>action('letter-copy',async()=>{const d=details();if(navigator.clipboard?.write&&window.ClipboardItem){const image=await logo();await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([letterHtml(d,image.data)],{type:'text/html'}),'text/plain':new Blob([['GEMS/WASTE Advisers','PO Box 2504, Chigumula, Blantyre, Malawi',...ids.map(id=>id==='date'?dateLabel(d[id]):d[id]),'Green Economies Made Simple'].filter(Boolean).join('\n\n')],{type:'text/plain'})})]);}else{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(preview);selection.removeAllRanges();selection.addRange(range);const ok=document.execCommand('copy');selection.removeAllRanges();if(!ok)throw Error('Copy blocked');}const button=document.getElementById('letter-copy');button.textContent='✓ Copied!';button.classList.add('copied');message('Copied. Paste into Word using Keep Source Formatting.');}));
render();
})();